def transform(grid):
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    for r, row in enumerate(grid):
        cols = [c for c, x in enumerate(row) if x != bg]
        if len(cols) >= 2:
            for a, b in zip(cols, cols[1:]):
                if b - a == 2 and row[a] == row[b]:
                    out[r][a + 1] = 2
    return out
